SELECT IGAEJUNG_NO, SNAME, ISEQ, SDIFF_YN, SDEL_YN, SUBSTR(SINS_DT, 1, 16) AS SINS_DT FROM TB_GAEJUNG WHERE SDEL_YN = 'N'
AND UPPER(SNAME) LIKE '%' || UPPER(#{searchKeyword}) || '%'
ORDER BY ISEQ, IGAEJUNG_NO LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM TB_PROM
 WHERE IGAEJUNG_NO   = #{gaejungNo}
   AND SEXISTING_YN = 'Y'

mapper.update:
UPDATE TB_GAEJUNG SET
	SNAME    = #{gaejungNm},
	ISEQ     = #{seq},
	SDIFF_YN = #{diffYn},
	SDEL_YN  = #{delYn}
WHERE IGAEJUNG_NO = #{gaejungNo}
